import { apiClient } from "@/lib/apiClient";

/**
 * Şifreyi token ile sıfırla — apiv3 `POST /auth/reset-password` (app.token,
 * tarayıcı → /api/apiv3 proxy). apiv3 HAM status string döner
 * ("passwords.reset" / "passwords.token" ...); çağıran doğrudan karşılaştırır.
 */
export default function postChangePassword({
    email,
    token,
    password,
    passwordConfirmation,
}: {
    email: string;
    token: string;
    password: string;
    passwordConfirmation: string;
}) {
    return apiClient<string>("/auth/reset-password", {
        method: "POST",
        body: {
            email,
            token,
            password,
            password_confirmation: passwordConfirmation,
        },
    });
}
