"use client";
import { useEffect, useState } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import postChangePassword from "@/services/auth/passwordChangeService";

export default function Page({ searchParams }: { searchParams: any }) {
  const [password, setPassword] = useState("");
  const [passwordConfirmation, setPasswordConfirmation] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [success, setSuccess] = useState(false);
  const [countdown, setCountdown] = useState(5);

  // Şifre değişince oturum AÇILMAZ (apiv3 reset yalnızca parolayı günceller,
  // token döndürmez); bu yüzden ana sayfaya değil giriş ekranına götürüyoruz.
  useEffect(() => {
    if (!success) return;
    if (countdown <= 0) {
      window.location.href = "/auth/login";
      return;
    }
    const timer = setTimeout(() => setCountdown((c) => c - 1), 1000);
    return () => clearTimeout(timer);
  }, [success, countdown]);

  const resetSubmit = async () => {
    if (password && passwordConfirmation && password === passwordConfirmation) {
      setErrorMessage("");
      try {
        setLoading(true);
        const res = await postChangePassword({
          email: searchParams.email,
          token: searchParams.token,
          password,
          passwordConfirmation,
        });
        setLoading(false);

        if (res == "passwords.reset") {
          setSuccess(true);
        } else if (res == "passwords.token") {
          setErrorMessage(
            "Invalid operation. Please request a new password reset or contact support if your problem is not resolved.",
          );
        } else {
          setLoading(false);
          setErrorMessage(
            "A problem occurred due to the system. Please try again later or contact customer service.",
          );
        }
      } catch (error: any) {
        setLoading(false);
        setErrorMessage(
          "A problem occurred due to the system. Please try again later or contact customer service.",
        );
      }
    } else
      setErrorMessage(
        "Your password must be at least 8 characters and match confirm.",
      );
  };

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-4 tw-font-display">
        <Breadcrumb
          items={[
            { pageTitle: "Authentication", pageUrl: "/" },
            { pageTitle: "Reset Password", pageUrl: "/" },
          ]}
        />
        <div className="tw-flex tw-justify-center">
          <div className="tw-w-full tw-max-w-[440px]">
            <div
              className="tw-bg-white tw-rounded-[20px] tw-p-6 md:tw-p-8"
              style={{ boxShadow: "0 4px 24px rgba(20,16,28,0.08)" }}
            >
              {success ? (
                <div className="tw-text-center">
                  <div
                    className="tw-w-14 tw-h-14 tw-mx-auto tw-mb-4 tw-rounded-full tw-flex tw-items-center tw-justify-center"
                    style={{ background: "rgba(34,197,94,0.12)" }}
                    aria-hidden="true"
                  >
                    <svg
                      width="28"
                      height="28"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="#16a34a"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M20 6 9 17l-5-5" />
                    </svg>
                  </div>
                  <h1
                    className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-2 tw-mt-0"
                    role="status"
                    aria-live="polite"
                  >
                    Your password has been changed
                  </h1>
                  <p className="tw-text-[14px] tw-text-[#5d556c] tw-mb-6 tw-mt-0">
                    You can now sign in to{" "}
                    <span className="tw-font-semibold tw-text-[#2a2336]">
                      {searchParams.email}
                    </span>{" "}
                    with your new password.
                  </p>
                  <a
                    href="/auth/login"
                    className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-px-[22px] tw-py-3.5 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[15px] tw-font-semibold tw-no-underline tw-transition-colors"
                  >
                    Go to login
                  </a>
                  <p className="tw-text-[13px] tw-text-[#8b8397] tw-mt-4 tw-mb-0">
                    Redirecting to the login page in {countdown}...
                  </p>
                </div>
              ) : (
                <>
                  <h1 className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-1 tw-mt-0">
                    Reset your password
                  </h1>
                  <p className="tw-text-[14px] tw-text-[#5d556c] tw-mb-5 tw-mt-0">
                    {searchParams.email}
                  </p>

                  {errorMessage && (
                    <div
                      role="alert"
                      className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]"
                      style={{ background: "rgba(239,68,68,0.08)" }}
                    >
                      {errorMessage}
                    </div>
                  )}

                  <div
                    className="tw-mb-5 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#1d4ed8]"
                    style={{ background: "rgba(59,130,246,0.08)" }}
                    role="alert"
                  >
                    - The password must be at least 8 characters.
                    <br />- The two passwords must match each other.
                  </div>

                  <div className="tw-flex tw-flex-col tw-gap-4">
                    <div className="tw-flex tw-flex-col tw-gap-1.5">
                      <label
                        htmlFor="passwordInput"
                        className="tw-text-[13px] tw-font-semibold tw-text-[#2a2336]"
                      >
                        Password
                      </label>
                      <input
                        type="password"
                        className="tw-w-full tw-px-3.5 tw-py-3 tw-rounded-[10px] tw-text-[16px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid tw-border-[#d8d2e1] focus:tw-border-[#854ec9] tw-bg-white tw-transition-colors"
                        id="passwordInput"
                        onChange={(event: any) => {
                          setPassword(event.target.value);
                        }}
                      />
                    </div>
                    <div className="tw-flex tw-flex-col tw-gap-1.5">
                      <label
                        htmlFor="passwordConfirmationInput"
                        className="tw-text-[13px] tw-font-semibold tw-text-[#2a2336]"
                      >
                        Password confirmation
                      </label>
                      <input
                        type="password"
                        className="tw-w-full tw-px-3.5 tw-py-3 tw-rounded-[10px] tw-text-[16px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid tw-border-[#d8d2e1] focus:tw-border-[#854ec9] tw-bg-white tw-transition-colors"
                        id="passwordConfirmationInput"
                        onChange={(event: any) => {
                          setPasswordConfirmation(event.target.value);
                        }}
                      />
                    </div>
                    {loading ? (
                      <button
                        className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-px-[22px] tw-py-3.5 tw-rounded-full tw-bg-[#854ec9] tw-text-white tw-text-[15px] tw-font-semibold tw-border-0 tw-cursor-not-allowed tw-opacity-60"
                        type="button"
                        disabled
                      >
                        <span
                          className="tw-inline-block tw-w-4 tw-h-4 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
                          aria-hidden="true"
                        ></span>
                        <span role="status">Loading...</span>
                      </button>
                    ) : (
                      <button
                        type="button"
                        className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-px-[22px] tw-py-3.5 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[15px] tw-font-semibold tw-border-0 tw-cursor-pointer tw-transition-colors"
                        onClick={resetSubmit}
                      >
                        Submit
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
